 [STAThread]static int Main(string[] args){Store.Root=args[0];Directory.CreateDirectory(Store.Root);Check(new Config().SkinShuffleMusicMode=="seated","quiet seated changes are the default");var c=new Config{SkinShuffleMusicMode="bad"};c.Validate();Check(c.SkinShuffleMusicMode=="seated","invalid music modes fall back to seated continuity");c.SkinShuffleMusicMode="stand-first";var imported=PreferenceReview.Parse(PreferenceTransfer.Export(c,false));Check(imported.PresentKeys.Contains("SkinShuffleMusicMode")&&imported.Preferences.SkinShuffleMusicMode=="stand-first","music mode round trips with common preferences");
