   foreach(bool manual in new[]{false,true}){pet.Settings.SkinShuffleMusicMode="seated";string last=(string)F(pet,"lastSkinAction");string target=Other(pet);if(manual)pet.SelectSkin(target);else Request(pet);Check(pet.Settings.Skin==target&&pet.CurrentAction=="music-quiet"&&!Running(pet),"seated mode keeps the current music action: manual="+manual);Check((double)F(pet,"stateAt")==phase&&ReferenceEquals(planner,F(pet,"musicReactionPlanner"))&&Equals(entered,F(planner,"enteredAt"))&&(string)F(pet,"lastSkinAction")==last,"seated mode preserves phase, planner and standing-action history: manual="+manual);}
