    At(pet,720);double started=(double)F(pet,"skinShowcaseAt");Check((bool)F(pet,"skinVisualRunning")&&(bool)F(pet,"skinShowcaseSwapStarted")&&pet.CurrentAction=="groom","costume fade starts only after the old skin has stood up");Check(ReferenceEquals(((Image)F(pet,"sprite")).Source,sequence.Source.Frame(AnimationGallery.Catalog.First(a=>a.Id=="groom"),0).Source),"new skin starts its selected action at the fade boundary");await Task.Delay(350);Check(Running(pet)&&!(bool)F(pet,"skinVisualRunning")&&(double)F(pet,"skinShowcaseAt")==started&&pet.CurrentAction=="groom","fade completion continues the action rather than replaying rise");At(pet,1320);Snapshot(pet,"new-action.png");At(pet,3120);Check(ReferenceEquals(((Image)F(pet,"sprite")).Source,sequence.Source.Frame(AnimationGallery.Catalog.First(a=>a.Id=="music-sit"),300).Source),"sit frames belong to the new skin");Snapshot(pet,"new-sit.png");At(pet,3560);Check(!Running(pet)&&pet.CurrentAction=="music-quiet"&&(double)F(pet,"stateAt")==phase&&Equals(entered,F(planner,"enteredAt")),"standing sequence resumes the untouched music phase");Snapshot(pet,"seated-again.png");
    pet.SelectSkin(Other(pet));At(pet,200);var originalOld=Sequence(pet).OldSource;pet.SelectSkin(Other(pet));Check(pet.CurrentAction=="music-rise"&&ReferenceEquals(originalOld,Sequence(pet).OldSource),"rapid replacement during rise keeps the original visible old skin");At(pet,720);await Task.Delay(350);At(pet,1320);pet.SelectSkin(Other(pet));Check(pet.CurrentAction=="groom"&&(bool)F(pet,"skinShowcaseSwapStarted"),"rapid replacement during action does not restart a rise");Call(pet,"StopSkinVisual");
