   pet.Settings.SmoothTransitions=false;pet.Settings.LinkChatGPT=true;foreach(string task in new[]{"running","waiting","failed","review"}){Set(pet,"state",task);phase=Now(pet)-.4;Set(pet,"stateAt",phase);pet.Link.Current=new BridgeState{Connected=true,State=task,At=DateTime.UtcNow,NotificationCount=1,Notices=new[]{new BridgeNotice{State=task,Id="keep"}}};var link=pet.Link.Current;var notices=link.Notices;var now=Now(pet);string target=Other(pet);Request(pet);Check(pet.Settings.Skin==target&&!pet.SkinShuffleRequested&&pet.CurrentAction==task&&!Running(pet),"explicit skin-only change stays in task pose: "+task);var frames=(Dictionary<string,BitmapSource[]>)F(pet,"frames");int row=Rules.Row(task),frame=Rules.Frame(task,(now-phase)*1000);Check(ReferenceEquals(((Image)F(pet,"sprite")).Source,frames[target][row*8+frame]),"task phase uses the corresponding target-skin frame: "+task);Check((double)F(pet,"stateAt")==phase&&ReferenceEquals(link,pet.Link.Current)&&ReferenceEquals(notices,pet.Link.Current.Notices)&&link.NotificationCount==1&&F(pet,"interaction")==null,"task skin change preserves task data, unread state and phase: "+task);}
