   pet.OpenSettings();var settings=(SettingsWindow)F(pet,"settingsWindow");settings.NavigateCategory("外观与互动","");((Expander)F(settings,"skinShuffleSection")).IsExpanded=true;var mode=(ComboBox)F(settings,"skinMusicMode");mode.SelectedIndex=0;Check(Store.Load().SkinShuffleMusicMode=="seated","settings can persist the quiet mode");mode.SelectedIndex=1;Check(Store.Load().SkinShuffleMusicMode=="stand-first","settings can persist the standing mode");((Button)F(settings,"skinActionPreviewButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var preview=(OutfitActionPreview)F(settings,"skinActionPreview");((CheckBox)F(preview,"cycle")).IsChecked=false;((CheckBox)F(preview,"seated")).IsChecked=true;var previewMode=(ComboBox)F(preview,"musicMode");previewMode.SelectedIndex=0;Check(((OutfitActionSequence)F(preview,"sequence")).StaySeated&&((OutfitActionSequence)F(preview,"sequence")).RiseMs==0,"preview can test seated continuity without a standing action");CaptureElement((FrameworkElement)preview.Content,"preview-seated.png");previewMode.SelectedIndex=1;await Task.Delay(1100);CaptureElement((FrameworkElement)preview.Content,"preview-stand-first.png");Check(!((OutfitActionSequence)F(preview,"sequence")).StaySeated&&((OutfitActionSequence)F(preview,"sequence")).RiseMs==720,"preview can test the stand-first sequence");Check(Store.Load().SkinShuffleMusicMode=="stand-first","preview mode switching does not write real preferences");preview.Close();pet.Settings.SkinShufflePool=SkinShuffleRules.Defaults.ToArray();settings.UpdateStatus();CaptureElement((FrameworkElement)settings.Content,"settings.png");settings.Close();
   Check(((DispatcherTimer)F(pet,"poll")).Interval==poll&&((DispatcherTimer)F(pet,"musicTimer")).Interval==musicPoll,"all modes retain provider polling intervals");passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);Store.Atomic("result.json",new{passed,checks,names});return passed?0:1;
